var PARTICLES = [{"p": "は", "name": "主題", "uses": [["L1", "提示主題（句子的主角）", "私は学生です。", "我是學生。"], ["L6", "對比・否定時常用は", "魚は食べません。", "（魚的話）我不吃。"], ["L10", "位置句的主題", "銀行は駅の前にあります。", "銀行在車站前面。"], ["L16", "大主題＋小主題（〜は〜が）", "東京は人が多いです。", "東京人很多。"]]}, {"p": "が", "name": "主語・對象", "uses": [["L10", "存在句的主語（あります／います）", "机の上に本があります。", "桌上有書。"], ["L9", "喜好・能力・理解的對象", "音楽が好きです。日本語がわかります。", "喜歡音樂。懂日文。"], ["L13", "想要的東西（ほしい／たい）", "新しい車がほしいです。", "想要新車。"], ["L12", "疑問詞當主語", "どちらが好きですか。だれが来ましたか。", "喜歡哪一個？誰來了？"], ["L16", "描述特徵（〜は〜が）", "象は鼻が長いです。", "大象鼻子很長。"], ["L18", "能力（できます）", "日本語ができます。", "會日文。"], ["L8", "逆接「但是」（句中的が）", "すみませんが、もう一度お願いします。", "不好意思，請再說一次。"]]}, {"p": "を", "name": "受詞", "uses": [["L6", "動作的直接受詞", "パンを食べます。本を読みます。", "吃麵包。看書。"], ["L13", "離開的地點", "7時にうちを出ます。", "七點離開家。"], ["L23", "經過・移動的場所", "公園を散歩します。橋を渡ります。", "在公園散步。過橋。"]]}, {"p": "に", "name": "時間・地點・對象", "uses": [["L4", "時間點", "7時に起きます。日曜日に行きます。", "七點起床。星期天去。"], ["L5", "目的地（＝へ）", "東京に行きます。", "去東京。"], ["L10", "存在的地點", "部屋に猫がいます。", "房間裡有貓。"], ["L7", "給予・接收的對象", "友達に電話をかけます。母に花をもらいました。", "打電話給朋友。從媽媽那裡收到花。"], ["L13", "去做某事的目的", "デパートへ買い物に行きます。", "去百貨公司買東西。"], ["L6", "會面・搭乘的對象", "友達に会います。電車に乗ります。", "見朋友。搭電車。"], ["L11", "頻率", "1週間に2回日本語を勉強します。", "一週學兩次日文。"], ["L13", "進入的地點", "喫茶店に入ります。", "進咖啡廳。"], ["L19", "變化的結果（なります）", "医者になります。", "成為醫生。"]]}, {"p": "で", "name": "地點・手段", "uses": [["L6", "動作發生的地點", "学校で勉強します。", "在學校唸書。"], ["L5", "交通工具", "電車で行きます。", "搭電車去。"], ["L7", "工具・語言・方法", "はしで食べます。日本語で話します。", "用筷子吃。用日文說。"], ["L12", "範圍（最高級）", "日本で富士山がいちばん高いです。", "在日本，富士山最高。"], ["L11", "合計", "りんごは三つで六百円です。", "蘋果三顆六百圓。"], ["L16", "な形容詞・名詞的連接", "簡単で便利です。", "既簡單又方便。"]]}, {"p": "へ", "name": "方向", "uses": [["L5", "移動的方向（＝に；へ強調方向，に強調到達點）", "日本へ行きます。", "去日本。"]]}, {"p": "と", "name": "和・引用", "uses": [["L1-3", "並列「和」（全部列出）", "本とノートを買いました。", "買了書和筆記本。"], ["L5", "一起（同伴）", "友達と映画を見ます。", "和朋友看電影。"], ["L21", "引用（思います／言います）", "明日は雨だと思います。", "我覺得明天會下雨。"], ["L23", "條件「一…就…」", "このボタンを押すと、お釣りが出ます。", "一按這個按鈕，零錢就出來。"]]}, {"p": "も", "name": "也", "uses": [["L1", "「也」", "私も学生です。", "我也是學生。"], ["L5", "疑問詞＋も＋否定（全面否定）", "どこへも行きません。何も食べませんでした。", "哪裡都不去。什麼都沒吃。"], ["L9", "〜も〜も「都」", "肉も魚も好きです。", "肉和魚都喜歡。"]]}, {"p": "から・まで", "name": "起訖・原因", "uses": [["L4", "時間・地點的起點和終點", "9時から5時まで働きます。うちから駅まで歩きます。", "從九點工作到五點。從家走到車站。"], ["L9", "原因（接在原因句尾）", "時間がありませんから、タクシーで行きます。", "因為沒時間，所以搭計程車去。"], ["L7", "來源（＝に）", "先生から手紙をもらいました。", "從老師那裡收到信。"], ["L16", "〜てから「…之後」", "仕事が終わってから、飲みに行きます。", "工作結束後去喝一杯。"], ["L17", "〜までに「在…之前（期限）」", "金曜日までにレポートを出します。", "星期五前交報告。"]]}, {"p": "の", "name": "的", "uses": [["L1", "所有・所屬・說明", "これは私の本です。日本語の先生です。", "這是我的書。是日文老師。"], ["L2", "代替名詞「…的（東西）」", "この傘はだれのですか。…私のです。", "這把傘是誰的？…是我的。"], ["L10", "連接方位詞", "机の上に本があります。", "桌上有書。"]]}, {"p": "か", "name": "疑問・或者", "uses": [["L1", "疑問句尾", "学生ですか。", "是學生嗎？"], ["L12", "「或者」", "コーヒーか紅茶を飲みます。", "喝咖啡或紅茶。"], ["L13", "疑問詞＋か「某…」", "何か食べませんか。どこかへ行きましたか。", "要不要吃點什麼？有去哪裡嗎？"]]}, {"p": "ね・よ", "name": "句尾語氣", "uses": [["L4", "ね：確認・尋求同意「…呢／對吧」", "いい天気ですね。", "天氣真好呢。"], ["L6", "よ：告訴對方不知道的事「…喔」", "この店は安いですよ。", "這家店很便宜喔。"]]}, {"p": "より・ほう・いちばん", "name": "比較", "uses": [["L12", "AはBより「A比B…」", "飛行機は電車より速いです。", "飛機比電車快。"], ["L12", "どちらが…／…のほうが", "肉と魚と、どちらが好きですか。…魚のほうが好きです。", "肉和魚喜歡哪個？…比較喜歡魚。"], ["L12", "〜の中で…がいちばん", "家族の中で父がいちばん背が高いです。", "家人之中爸爸最高。"]]}, {"p": "や・だけ", "name": "舉例・只有", "uses": [["L10", "や〜など「…和…等等」（沒列完）", "冷蔵庫の中に卵や牛乳などがあります。", "冰箱裡有蛋、牛奶等等。"], ["L11", "だけ「只有」", "一つだけください。", "請給我一個就好。"]]}, {"p": "ましょう・ませんか・ましょうか", "name": "邀請・提議", "uses": [["L6", "〜ませんか：邀請對方「要不要…？」", "いっしょに昼ご飯を食べませんか。", "要不要一起吃午餐？"], ["L6", "〜ましょう：提議或答應「…吧」", "ええ、食べましょう。駅で会いましょう。", "好啊，吃吧。車站見。"], ["L14", "〜ましょうか：主動提議幫忙「我來…好嗎？」", "荷物を持ちましょうか。…すみません、お願いします。", "我來幫你拿行李好嗎？…不好意思，麻煩你了。"], ["L14", "拒絕 ましょうか 的說法", "いいえ、けっこうです。／大丈夫です。", "不用了，謝謝。／沒關係。"]]}];
